import{_ as t,o as n,c as s,a5 as e}from"./chunks/framework.DJo0M80U.js";const h=JSON.parse('{"title":"41. Standard I/O and printf/scanf","description":"The Little Book of C — 41. Standard I/O and printf/scanf","frontmatter":{"title":"41. Standard I/O and printf/scanf","date":"2026-07-04","categories":["C 教程"],"tags":["C","Little Book of C","Input Output and Files"],"description":"The Little Book of C — 41. Standard I/O and printf/scanf","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","section":41,"sidebarWeight":41,"lang":"en-US","alternateEn":"/posts/c教程/en-US/05-Input Output and Files/041-Standard IO and printfscanf","alternateZh":"/posts/c教程/zh-CN/05-输入输出与文件/041-Standard IO and printfscanf"},"headers":[],"relativePath":"posts/c教程/en-US/05-Input Output and Files/041-Standard IO and printfscanf.md","filePath":"posts/c教程/en-US/05-Input Output and Files/041-Standard IO and printfscanf.md","lastUpdated":1790163617000}'),i={name:"posts/c教程/en-US/05-Input Output and Files/041-Standard IO and printfscanf.md"};function p(o,a,d,r,l,c){return n(),s("div",null,[...a[0]||(a[0]=[e(`<p>[中文版本](/posts/c教程/zh-CN/05-输入输出与文件/041-Standard IO and printfscanf)</p><p>Input and output are how your programs talk to the outside world. In C, almost everything goes through the Standard I/O library, defined in<code>&lt;stdio.h&gt;</code>. You’ve already met<code>printf()</code> in “Hello, C World”, now you’ll learn how all these functions fit together, how they work, and how to use them safely.</p><h4 id="the-standard-streams" tabindex="-1">The Standard Streams <a class="header-anchor" href="#the-standard-streams" aria-label="Permalink to &quot;The Standard Streams&quot;">​</a></h4><p>Every C program starts with three standard streams automatically open:</p><table tabindex="0"><thead><tr><th>Stream</th><th>Purpose</th><th>Example Function</th></tr></thead><tbody><tr><td><code>stdin</code></td><td>Standard input (keyboard, or redirected file)</td><td><code>scanf()</code>,<code>fgets()</code></td></tr><tr><td><code>stdout</code></td><td>Standard output (screen)</td><td><code>printf()</code>,<code>puts()</code></td></tr><tr><td><code>stderr</code></td><td>Standard error (screen, for diagnostics)</td><td><code>fprintf(stderr, ...)</code></td></tr></tbody></table><p>You can redirect these streams in the terminal:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./program &lt; input.txt &gt; output.txt 2&gt; errors.log</span></span></code></pre></div><h4 id="printing-with-printf" tabindex="-1">Printing with printf() <a class="header-anchor" href="#printing-with-printf" aria-label="Permalink to &quot;Printing with printf()&quot;">​</a></h4><p><code>printf()</code> formats and prints data to<code>stdout</code>. Its power lies in format specifiers, which describe the type and layout of what to print.</p><table tabindex="0"><thead><tr><th>Type</th><th>Format</th><th>Example</th></tr></thead><tbody><tr><td>int</td><td><code>%d</code></td><td><code>printf(&quot;%d&quot;, 42);</code></td></tr><tr><td>float</td><td><code>%f</code></td><td><code>printf(&quot;%.2f&quot;, 3.1415);</code></td></tr><tr><td>char</td><td><code>%c</code></td><td><code>printf(&quot;%c&quot;, &#39;A&#39;);</code></td></tr><tr><td>string</td><td><code>%s</code></td><td><code>printf(&quot;%s&quot;, &quot;Hello&quot;);</code></td></tr><tr><td>pointer</td><td><code>%p</code></td><td><code>printf(&quot;%p&quot;, ptr);</code></td></tr><tr><td>hexadecimal</td><td><code>%x</code></td><td><code>printf(&quot;%x&quot;, 255);</code></td></tr></tbody></table><p>You can control width, precision, and alignment:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>printf(&quot;%-10s | %6.2f\\n&quot;, &quot;Price&quot;, 3.5);</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Price      |   3.50</span></span></code></pre></div><h4 id="tiny-code-print-everything" tabindex="-1">Tiny Code: Print Everything <a class="header-anchor" href="#tiny-code-print-everything" aria-label="Permalink to &quot;Tiny Code: Print Everything&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    int i = 42;</span></span>
<span class="line"><span>    float f = 3.1415;</span></span>
<span class="line"><span>    char c = &#39;C&#39;;</span></span>
<span class="line"><span>    char *s = &quot;Hello, C!&quot;;</span></span>
<span class="line"><span>    printf(&quot;Integer: %d\\n&quot;, i);</span></span>
<span class="line"><span>    printf(&quot;Float: %.2f\\n&quot;, f);</span></span>
<span class="line"><span>    printf(&quot;Char: %c\\n&quot;, c);</span></span>
<span class="line"><span>    printf(&quot;String: %s\\n&quot;, s);</span></span>
<span class="line"><span>    printf(&quot;Pointer: %p\\n&quot;, (void*)s);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Integer: 42</span></span>
<span class="line"><span>Float: 3.14</span></span>
<span class="line"><span>Char: C</span></span>
<span class="line"><span>String: Hello, C!</span></span>
<span class="line"><span>Pointer: 0x7ffeed001234</span></span></code></pre></div><h4 id="reading-with-scanf" tabindex="-1">Reading with scanf() <a class="header-anchor" href="#reading-with-scanf" aria-label="Permalink to &quot;Reading with scanf()&quot;">​</a></h4><p><code>scanf()</code> reads formatted input from<code>stdin</code>. It’s like<code>printf()</code> in reverse, you tell it the format, and it fills your variables.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int age;</span></span>
<span class="line"><span>float height;</span></span>
<span class="line"><span>printf(&quot;Enter age and height: &quot;);</span></span>
<span class="line"><span>scanf(&quot;%d %f&quot;, &amp;age, &amp;height);</span></span>
<span class="line"><span>printf(&quot;You are %d years old and %.1f meters tall.\\n&quot;, age, height);</span></span></code></pre></div><p>Input:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>25 1.75</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>You are 25 years old and 1.8 meters tall.</span></span></code></pre></div><p>Always use the<code>&amp;</code> operator for non-array variables — it passes the memory address where the value should be stored.</p><h4 id="safer-input-fgets-and-sscanf" tabindex="-1">Safer Input: fgets() and sscanf() <a class="header-anchor" href="#safer-input-fgets-and-sscanf" aria-label="Permalink to &quot;Safer Input: fgets() and sscanf()&quot;">​</a></h4><p><code>scanf()</code> is risky for strings, it doesn’t prevent buffer overflow. Safer pattern: use<code>fgets()</code> to read a full line, then parse it.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>char buf[100];</span></span>
<span class="line"><span>printf(&quot;Enter your name: &quot;);</span></span>
<span class="line"><span>fgets(buf, sizeof(buf), stdin);</span></span>
<span class="line"><span>buf[strcspn(buf, &quot;\\n&quot;)] = &#39;\\0&#39;; // remove newline</span></span>
<span class="line"><span>printf(&quot;Hello, %s!\\n&quot;, buf);</span></span></code></pre></div><h4 id="combining-printf-and-scanf" tabindex="-1">Combining printf and scanf <a class="header-anchor" href="#combining-printf-and-scanf" aria-label="Permalink to &quot;Combining printf and scanf&quot;">​</a></h4><p>You can build interactive console tools easily:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    char name[50];</span></span>
<span class="line"><span>    int year;</span></span>
<span class="line"><span>    printf(&quot;Enter your name: &quot;);</span></span>
<span class="line"><span>    scanf(&quot;%49s&quot;, name); // limit input to 49 chars + null</span></span>
<span class="line"><span>    printf(&quot;Enter your birth year: &quot;);</span></span>
<span class="line"><span>    scanf(&quot;%d&quot;, &amp;year);</span></span>
<span class="line"><span>    printf(&quot;Hi %s! You are about %d years old.\\n&quot;, name, 2025 - year);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Enter your name: Alice</span></span>
<span class="line"><span>Enter your birth year: 2000</span></span>
<span class="line"><span>Hi Alice! You are about 25 years old.</span></span></code></pre></div><h4 id="formatted-output-to-files-and-strings" tabindex="-1">Formatted Output to Files and Strings <a class="header-anchor" href="#formatted-output-to-files-and-strings" aria-label="Permalink to &quot;Formatted Output to Files and Strings&quot;">​</a></h4><p>You can redirect formatted output anywhere, not just the screen.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>fprintf(stderr, &quot;Error: invalid input.\\n&quot;); // print to stderr</span></span>
<span class="line"><span>char buffer[50];</span></span>
<span class="line"><span>sprintf(buffer, &quot;Pi = %.3f&quot;, 3.14159); // print to string</span></span>
<span class="line"><span>puts(buffer);</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Pi = 3.142</span></span></code></pre></div><h4 id="why-it-matters" tabindex="-1">Why It Matters <a class="header-anchor" href="#why-it-matters" aria-label="Permalink to &quot;Why It Matters&quot;">​</a></h4><p><code>printf()</code> and<code>scanf()</code> are the workhorses of console I/O. They teach you:</p><ul><li>How data moves between memory and streams.</li><li>How to control numeric precision and layout.</li><li>How input and output interact with the terminal or files.</li></ul><p>Every C system, from tiny microcontrollers to full operating systems, uses these same foundations.</p><h4 id="try-it-yourself" tabindex="-1">Try It Yourself <a class="header-anchor" href="#try-it-yourself" aria-label="Permalink to &quot;Try It Yourself&quot;">​</a></h4><ol><li>Print a table of numbers with two columns: number and its square.</li><li>Read three integers using<code>scanf</code> and print their average.</li><li>Use<code>fgets</code> and<code>sscanf</code> to safely parse<code>&quot;42 3.14&quot;</code> into int and float.</li><li>Write a small quiz app: ask a question, read input, print “Correct” or “Try again”.</li><li>Experiment with printing to<code>stderr</code>, redirect errors to a file.</li></ol><p>Mastering standard I/O is like mastering your program’s voice, it’s how your C code speaks and listens. Next, you’ll move deeper into file handling, learning how to open, read, and write files with file pointers in Section 42.</p>`,46)])])}const f=t(i,[["render",p]]);export{h as __pageData,f as default};
